namespace krmemory::json {
struct Value { using Object=std::map<std::string,Value,std::less<>>;using Array=std::vector<Value>;std::variant<std::nullptr_t,bool,double,std::string,Array,Object> data{nullptr};bool is_object()const{return std::holds_alternative<Object>(data);}const Object& object()const{return std::get<Object>(data);}const Value* get(std::string_view k)const{if(!is_object())return{};auto i=object().find(k);return i==object().end()?nullptr:&i->second;}const std::string* string()const{return std::get_if<std::string>(&data);}const Array* array()const{return std::get_if<Array>(&data);} };
class Parser {std::string_view s;size_t p{};void ws(){while(p<s.size()&&std::isspace((unsigned char)s[p]))++p;}char take(){if(p>=s.size())throw std::runtime_error("truncated JSON");return s[p++];}static int hex(char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;throw std::runtime_error("invalid unicode escape");}std::uint32_t codepoint(){if(p+4>s.size())throw std::runtime_error("truncated unicode escape");std::uint32_t x{};for(int i=0;i<4;++i)x=(x<<4)|hex(take());return x;}static void utf8(std::string& out,std::uint32_t x){if(x<=0x7f)out+=char(x);else if(x<=0x7ff){out+=char(0xc0|(x>>6));out+=char(0x80|(x&63));}else if(x<=0xffff){out+=char(0xe0|(x>>12));out+=char(0x80|((x>>6)&63));out+=char(0x80|(x&63));}else if(x<=0x10ffff){out+=char(0xf0|(x>>18));out+=char(0x80|((x>>12)&63));out+=char(0x80|((x>>6)&63));out+=char(0x80|(x&63));}else throw std::runtime_error("invalid unicode codepoint");}std::string str(){std::string o;if(take()!='"')throw std::runtime_error("expected JSON string");while(p<s.size()){char c=take();if(c=='"')return o;if((unsigned char)c<0x20)throw std::runtime_error("control character in JSON string");if(c=='\\'){char e=take();if(e=='n')o+='\n';else if(e=='t')o+='\t';else if(e=='r')o+='\r';else if(e=='b')o+='\b';else if(e=='f')o+='\f';else if(e=='"'||e=='\\'||e=='/')o+=e;else if(e=='u'){auto x=codepoint();if(x>=0xd800&&x<=0xdbff){if(take()!='\\'||take()!='u')throw std::runtime_error("missing low surrogate");auto low=codepoint();if(low<0xdc00||low>0xdfff)throw std::runtime_error("invalid low surrogate");x=0x10000+((x-0xd800)<<10)+(low-0xdc00);}else if(x>=0xdc00&&x<=0xdfff)throw std::runtime_error("unexpected low surrogate");utf8(o,x);}else throw std::runtime_error("unsupported JSON escape");}else o+=c;}throw std::runtime_error("unterminated JSON string");}Value v(){ws();if(p>=s.size())throw std::runtime_error("missing JSON value");if(s[p]=='"')return Value{str()};if(s[p]=='{'){++p;Value::Object o;ws();while(p<s.size()&&s[p]!='}'){auto k=str();ws();if(take()!=':')throw std::runtime_error("expected colon");o.emplace(k,v());ws();if(s[p]==','){++p;ws();}else break;}if(take()!='}')throw std::runtime_error("expected object end");return Value{o};}if(s[p]=='['){++p;Value::Array a;ws();while(p<s.size()&&s[p]!=']'){a.push_back(v());ws();if(s[p]==','){++p;ws();}else break;}if(take()!=']')throw std::runtime_error("expected array end");return Value{a};}if(s.substr(p,4)=="true"){p+=4;return Value{true};}if(s.substr(p,5)=="false"){p+=5;return Value{false};}if(s.substr(p,4)=="null"){p+=4;return Value{nullptr};}size_t q=p;while(q<s.size()&&std::string_view("0123456789+-.eE").find(s[q])!=s.npos)++q;if(q==p)throw std::runtime_error("invalid JSON value");auto n=std::stod(std::string(s.substr(p,q-p)));p=q;return Value{n};}
public:explicit Parser(std::string_view x):s(x){}Value parse(){auto x=v();ws();if(p!=s.size())throw std::runtime_error("trailing JSON");return x;}};
inline Value parse(std::string_view s){return Parser(s).parse();}
}
